    "start_name_hint": "Your name will appear on official correspondence and, if necessary, memorial records.",
    "letter_go_to_end": "Go to final acknowledgment",
    "letter_scroll_hint": "Scroll to the end of the agreement to continue. Legal insists.",
    "loss_title": "REGION LOST",
    "loss_body": "No living personnel remain in Region {regionId}. CentroCom has closed the assignment file and opened a lessons-learned file of identical length.",
    "loss_mara": "There's nobody left to tell you it wasn't your fault, so I will. Go again if you can.",
    "scav_event_delay": "TEAM DELAYED / {siteName}: the route was worse than mapped. Return estimate +2 hours.",
    "scav_event_injury": "TEAM INJURY / {survivorName} was hurt at {siteName} ({damage} HP). The team is continuing.",
    "scav_event_cargo": "CARGO LOSS / {siteName}: part of the haul was dropped during a hasty exit. Remaining cargo is secure.",
    "scav_contact": "TEAM IN CONTACT / {teamName} reports infected near {location}. They are responding.",
    "phase2_transition_title": "CAMP CLASSIFICATION UPDATED: ESTABLISHED CAMP",
    "phase2_begin": "[ BEGIN PHASE 2 ]",
    "campaign_continue": "[ CONTINUE MANAGING OUTPOST ]",
    "campaign_menu": "[ RETURN TO MENU ]",
    "mara_closing": "Private channel. It's still me. CentroCom will send a certificate; I'm sending something less official. Thank you, {overseerName}. Keep them fed, keep the door working, and call me when the next authorization comes through.",
    "recovery_delivery": "EMERGENCY ALLOCATION / CentroCom has approved a one-time delivery of {resourceSummary}, arriving in 6 hours. This allocation has been noted in your file. In pencil, for now.",
    "component_reserve_warning": "COMPONENT RESERVE / This order leaves {components} Components. The Radio Relay needs 6. Continue anyway?",
    "job_general_worker": "Gathers salvage, carries it to storage and raises blueprints. Strength speeds the work. Officially 'flexible'; unofficially, everything nobody else was assigned.",
    "job_farmer": "Tends a garden plot through the work shift. Endurance speeds the crop. Food output is projected, not promised.",
    "job_engineer": "Builds and crafts at 1.5x. Strength speeds the work. Will build without a queue; the queue simply makes it look planned.",
    "job_medic": "Treats the injured at an aid station. Intelligence speeds the treatment. Liability coverage is pending review.",
    "job_guard": "Holds the perimeter and answers threats. Agility speeds the response. Bravery is encouraged but not reimbursed.",
    "job_scavenger": "Leads runs to regional sites. Agility speeds the search. Returns are expected; returns of personnel especially.",
    "reanimation_warning": "{survivorName} has reached terminal infection. Reanimation is expected within two hours. Isolate them in a medical bed or move everyone else away. CentroCom recommends both.",
    "broadcast_done": "Broadcast complete. {operatorName} read the invitation twice, in a calm and legally reviewed voice. Replies, if any, are expected within {minHours}-{maxHours} hours.",
    "candidate_expired": "{candidateName} stopped waiting for an answer. The channel remains open. Their opinion of the process has not been recorded.",
    "recruit_arrived": "{survivorName} has reached camp and been entered into the personnel register. Population: {population}. Food demand has been updated accordingly.",
    "threats_active_mara": "That was the demonstration. The rest won't be marked, and they won't wait for the work shift. Keep the watch staffed and the patrol close.",
    "relay_lost_mara": "The relay is down and the battery went with it. It will still be in the ruin up there. One more trip, a short one, and nobody needs to be brave about it."
